import {ICONS,ICON_SETS,ICON_GROUPS,searchIcons,materialSvg} from './icon-library.mjs';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const materialState={query:'',set:'all',group:'all',page:0};
export function materialPanel(picking=false,selected=''){
  return `<section class="material-browser" data-picking="${picking}" data-selected-icon="${esc(selected)}"><div class="material-toolbar"><label for="material-query" class="sr-only">搜索素材</label><input id="material-query" data-material-query placeholder="搜索：备份、电脑、代码、箭头 / cloud、laptop…" value="${esc(materialState.query)}"><label for="material-set" class="sr-only">图标库</label><select id="material-set" data-material-set><option value="all">所有图标库</option>${Object.entries(ICON_SETS).map(([id,name])=>`<option value="${id}" ${materialState.set===id?'selected':''}>${name}</option>`).join('')}</select></div><div class="material-groups">${Object.entries(ICON_GROUPS).map(([id,[name]])=>`<button data-material-group="${id}" class="filter ${materialState.group===id?'active':''}">${name}</button>`).join('')}</div><div data-material-results>${materialResults(picking,selected)}</div></section>`;
}
export function materialResults(picking,selected){
  const found=searchIcons(materialState.query,materialState.set,materialState.group),pages=Math.max(1,Math.ceil(found.length/60));
  materialState.page=Math.min(materialState.page,pages-1);
  const shown=found.slice(materialState.page*60,(materialState.page+1)*60);
  return `<div class="material-result-count">找到 ${found.length.toLocaleString('zh-CN')} 个素材 <span>本机 SVG · 无需联网</span></div><div class="material-grid">${shown.map(x=>`<button class="material-tile ${x.id===selected?'selected':''}" ${picking?'data-pick-icon':'data-inspect-icon'}="${esc(x.id)}" title="${esc(x.name)} · ${ICON_SETS[x.set]}" aria-label="${picking?'使用':'查看'} ${esc(x.id)}">${materialSvg(x.id)}<span>${esc(x.name)}</span><small>${ICON_SETS[x.set]}</small></button>`).join('')}</div>${!shown.length?'<div class="material-empty">试试更短的词，或用英文名称搜索。</div>':''}<div class="material-pagination"><button class="btn secondary small" data-material-page="${materialState.page-1}" ${materialState.page===0?'disabled':''}>上一页</button><span>${materialState.page+1} / ${pages}</span><button class="btn secondary small" data-material-page="${materialState.page+1}" ${materialState.page===pages-1?'disabled':''}>下一页</button></div>`;
}
export function materialPage(){return `<div class="page-heading"><div><div class="eyebrow">VISUAL DICTIONARY</div><h1>一个词，找到一个画面。</h1><p>${ICONS.length.toLocaleString('zh-CN')} 个矢量图标。先看素材，进入图卡环节再选用。</p></div></div><div class="info-box">每张图选一个有意义的符号就够了。线性或实心都可用，一期尽量保持同一种风格。</div><section class="panel" style="margin-top:24px">${materialPanel()}</section><p class="rule-foot">来源：<a href="https://github.com/lucide-icons/lucide" target="_blank" rel="noopener">Lucide</a> · <a href="https://github.com/tabler/tabler-icons" target="_blank" rel="noopener">Tabler</a>。许可随 HTML 和图片交付包提供。</p>`;}
